// SpecBoard がプロジェクト「最小の見本」から作ったファイルです。書き換えはプロジェクトで
import { z } from "zod";

// オブジェクトは z.strictObject です。未知のフィールドは strip されず拒否されます
// （JSON Schema 出力の additionalProperties: false と一致させています）。

// 循環参照・相互参照は Zod 4 のゲッター記法で表現しています。
// 型推論はそのまま効くので、追加の型注釈は要りません。

export const Memo = z.strictObject({
  field1: z.strictObject({
    get field1() { return Memo.optional(); },
    field2: z.string().optional(),
    field3: z.strictObject({
      field1: z.string().optional(),
      field2: z.string().optional(),
    }).optional(),
  }).optional(),
});
export type Memo = z.infer<typeof Memo>;
